package com.witchersbestiary.test;
import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import java.nio.file.*;import com.google.gson.*;import com.witchersbestiary.economy.*;import net.minecraft.item.*;
public final class Stage21ANetworkServer implements ModInitializer{
 private int phase,ticks;private final String[] names={"WBOne","WBTwo"};private final long[] nonces={21001,21002};private Path dir;
 private void command(int i,String action,long nonce)throws Exception{var j=new JsonObject();j.addProperty("nonce",nonce);j.addProperty("action",action);Files.writeString(dir.resolve(names[i]+".command.json"),j.toString());}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.stage21aNetwork"))return;dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));if(Files.exists(dir.resolve("wallet-resume.json")))phase=3;ServerTickEvents.END_SERVER_TICK.register(s->{try{ticks++;if(phase==2){if(ticks>100)s.stop(false);return;}if(ticks>6000)throw new IllegalStateException("Bounded wallet network timeout");var a=s.getPlayerManager().getPlayer(names[0]);var b=s.getPlayerManager().getPlayer(names[1]);if(a==null||b==null)return;
 if(phase==0){for(int i=0;i<2;i++){var p=i==0?a:b;p.getInventory().clear();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(true);p.getInventory().selectedSlot=0;p.getInventory().setStack(0,new ItemStack(Currency.WALLET));p.getInventory().setStack(1,new ItemStack(Currency.CROWN,64));Currency.WALLET.use(p.getWorld(),p,net.minecraft.util.Hand.MAIN_HAND);command(i,"walletFlow",nonces[i]);}phase=1;}
 else if(phase==1){for(int i=0;i<2;i++){var f=dir.resolve(names[i]+".reply.json");if(!Files.exists(f))return;var j=JsonParser.parseString(Files.readString(f)).getAsJsonObject();if(j.get("nonce").getAsLong()!=nonces[i]||!j.get("status").getAsString().equals("wallet-pass"))return;var p=i==0?a:b;if(WalletTransactions.balance(p.getInventory().getStack(0))!=54||p.getInventory().count(Currency.CROWN)!=10)throw new IllegalStateException("Wallet conservation failed");}
 var transferred=a.getInventory().getStack(0);a.getInventory().setStack(0,ItemStack.EMPTY);b.getInventory().setStack(2,transferred);a.closeHandledScreen();b.closeHandledScreen();if(WalletTransactions.balance(b.getInventory().getStack(2))!=54)throw new IllegalStateException("Transfer failed");s.save(false,true,true);Files.writeString(dir.resolve("wallet-resume.json"),"{}");Files.writeString(dir.resolve("resume.json"),"{}");for(int i=0;i<2;i++)command(i,"wait",21500+i);phase=2;ticks=0;s.stop(false);}
 else if(phase==3){if(WalletTransactions.balance(b.getInventory().getStack(2))!=54||WalletTransactions.balance(b.getInventory().getStack(0))!=54||a.getInventory().count(Currency.CROWN)!=10)throw new IllegalStateException("Saved transfer/restart failed");b.getInventory().selectedSlot=2;Currency.WALLET.use(b.getWorld(),b,net.minecraft.util.Hand.MAIN_HAND);command(1,"walletProof",23000);phase=4;}
 else if(phase==4){var f=dir.resolve(names[1]+".reply.json");if(!Files.exists(f))return;var j=JsonParser.parseString(Files.readString(f)).getAsJsonObject();if(j.get("nonce").getAsLong()!=23000)return;Files.writeString(dir.resolve("complete.json"),"{\"complete\":true,\"wallet_gui_after_restart\":true,\"saved_transferred_balance\":true,\"controller_complete\":true}");for(int i=0;i<2;i++)command(i,"stop",24000+i);phase=2;ticks=0;}
 else if(phase==2&&ticks>100)s.stop(false);
 }catch(Exception e){try{Files.writeString(dir.resolve("failed.json"),e.toString());}catch(Exception ignored){}s.stop(false);}});}
}
